class Decoder8b10b:
    def __init__(self):
        self.reset()

    def reset(self):
        self.data=0
        self.valid=0
        self.control=0

    def process(self, control_in, decoder_in, decoder_valid_in):
        decoder_out=self.data
        decoder_valid_out=self.valid
        control_out=self.control
